export interface FactoryRun {
  factoryRunId: number;
  title: string;
  projectSlug: string;
  organizationSlug: string;
  prdModuleName: string;
  prdSnapshot: string;
  status: 'queued' | 'running' | 'succeeded' | 'failed' | 'canceled';
  triggeredByEmail: string;
  reviewPassed: boolean | null;
  reviewScoreSummary: string | null;
  gitBranchName: string | null;
  errorSummary: string | null;
  active: boolean;
  created_At: string;
  updated_at: string | null;
}

export interface FactoryRunListResponse {
  factoryRuns: FactoryRun[];
}

export type CreateFactoryRunRequest = Omit<FactoryRun, 'factoryRunId' | 'created_At' | 'updated_at'>;
export type UpdateFactoryRunRequest = Partial<Omit<FactoryRun, 'factoryRunId' | 'created_At' | 'updated_at'>>;

// GET ALL — POST /all_factoryRuns
export async function getAllFactoryRuns(params?: { projectSlug?: string; organizationSlug?: string; status?: string }): Promise<FactoryRun[]> {
  const payload: any = {};
  if (params?.projectSlug) payload.projectSlug = params.projectSlug;
  if (params?.organizationSlug) payload.organizationSlug = params.organizationSlug;
  if (params?.status) payload.status = params.status;

  const res = await fetch(BASE_URL + "/all_factoryRuns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRuns": [payload] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: FactoryRunListResponse = await res.json();
  return data.factoryRuns ?? [];
}

// CREATE — action: 1
export async function createFactoryRun(payload: CreateFactoryRunRequest): Promise<FactoryRun> {
  const res = await fetch(BASE_URL + "/factoryRuns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRuns": [{ "action": 1, ...payload, active: true }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data = await res.json();
  // Assuming backend returns the created object directly or an array with one object
  return Array.isArray(data) ? data[0] : data; 
}

// UPDATE — action: 2
export async function updateFactoryRun(id: number, payload: UpdateFactoryRunRequest): Promise<FactoryRun> {
  const res = await fetch(BASE_URL + "/factoryRuns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRuns": [{ "action": 2, "factoryRunId": id, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data = await res.json();
  // Assuming backend returns the updated object directly or an array with one object
  return Array.isArray(data) ? data[0] : data;
}

// DELETE — action: 3
export async function deleteFactoryRun(id: number): Promise<void> {
  const res = await fetch(BASE_URL + "/factoryRuns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRuns": [{ "action": 3, "factoryRunId": id }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
}

// GET ONE — POST /one_factoryRuns
export async function getFactoryRunById(id: number): Promise<FactoryRun | undefined> {
  const res = await fetch(BASE_URL + "/one_factoryRuns", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRuns": [{ "factoryRunId": id }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data = await res.json();
  // The backend might return an object directly or an array with one object under 'factoryRuns'
  return data.factoryRuns && Array.isArray(data.factoryRuns) ? data.factoryRuns[0] : undefined;
}
