                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Email del Disparador *"
                    labelPlacement="floating"
                    value={formState.triggeredByEmail}
                    onIonInput={(e: CustomEvent<any>) => setFormState(p => ({ ...p, triggeredByEmail: e.detail.value! }))}
                    required
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Rama Git"
                    labelPlacement="floating"
                    value={formState.gitBranchName}
                    onIonInput={(e: CustomEvent<any>) => setFormState(p => ({ ...p, gitBranchName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonTextarea
                    fill="outline"
                    label="Resumen PRD Snapshot"
                    labelPlacement="floating"
                    value={formState.prdSnapshot}
                    onIonInput={(e: CustomEvent<any>) => setFormState(p => ({ ...p, prdSnapshot: e.detail.value! }))}
                    rows={4}
                  />
                </div>
                {formState.status === 'failed' && (
                  <div className="wizard-field-group">
                    <IonTextarea
                      fill="outline"
                      label="Resumen de Errores"
                      labelPlacement="floating"
                      value={formState.errorSummary}
                      onIonInput={(e: CustomEvent<any>) => setFormState(p => ({ ...p, errorSummary: e.detail.value! }))}
                      rows={4}
                    />
                  </div>
                )}
                {(formState.status === 'succeeded' || formState.status === 'failed') && (
                  <div className="wizard-field-group">
                    <IonInput
                      fill="outline"
                      label="Resumen de Puntuación de Revisión"
                      labelPlacement="floating"
                      value={formState.reviewScoreSummary}
                      onIonInput={(e: CustomEvent<any>) => setFormState(p => ({ ...p, reviewScoreSummary: e.detail.value! }))}
                    />
                  </div>
                )}
                <IonButton expand="block" type="submit" disabled={saving}>
                  {saving ? <IonSpinner name="dots" /> : 'Guardar'}
                </IonButton>
              </div>
            </form>
          </IonContent>
        </IonModal>

        <IonModal isOpen={showDetailModal} onDidDismiss={() => setShowDetailModal(false)} className="factory-run-detail-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>Detalle de Ejecución de Fábrica</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => setShowDetailModal(false)}>Cerrar</IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            {selectedFactoryRun && (
              <div className="factory-run-detail-content">
                <h2 className="factory-run-detail-title">{selectedFactoryRun.title}</h2>
                <p><strong>ID de Ejecución:</strong> {selectedFactoryRun.factoryRunId}</p>
                <p><strong>Proyecto:</strong> {selectedFactoryRun.projectSlug}</p>
                <p><strong>Organización:</strong> {selectedFactoryRun.organizationSlug}</p>
                <p><strong>Módulo PRD:</strong> {selectedFactoryRun.prdModuleName}</p>
                <p><strong>Estado:</strong> <IonBadge color={getStatusColor(selectedFactoryRun.status)}>{selectedFactoryRun.status}</IonBadge></p>
                <p><strong>Disparado por:</strong> {selectedFactoryRun.triggeredByEmail}</p>
                <p><strong>Rama Git:</strong> {selectedFactoryRun.gitBranchName || 'N/A'}</p>
                <p><strong>Revisión Pasada:</strong> {selectedFactoryRun.reviewPassed === true ? 'Sí' : selectedFactoryRun.reviewPassed === false ? 'No' : 'N/A'}</p>
                <p><strong>Resumen de Puntuación de Revisión:</strong> {selectedFactoryRun.reviewScoreSummary || 'N/A'}</p>
                {selectedFactoryRun.status === 'failed' && <p><strong>Resumen de Errores:</strong> {selectedFactoryRun.errorSummary || 'N/A'}</p>}
                <p><strong>Activo:</strong> {selectedFactoryRun.active ? 'Sí' : 'No'}</p>
                <p><strong>Creado en:</strong> {toHermosillo(selectedFactoryRun.created_At)}</p>
                <p><strong>Última Actualización:</strong> {toHermosillo(selectedFactoryRun.updated_at)}</p>

                <div className="prd-snapshot-section">
                  <IonButton fill="clear" expand="block" onClick={() => setExpandedPrdSnapshot(expandedPrdSnapshot === selectedFactoryRun.factoryRunId ? null : selectedFactoryRun.factoryRunId)}>
                    PRD Snapshot
                    <IonIcon icon={expandedPrdSnapshot === selectedFactoryRun.factoryRunId ? chevronUpOutline : chevronDownOutline} slot="end" />
                  </IonButton>
                  {expandedPrdSnapshot === selectedFactoryRun.factoryRunId && (
                    <div className="prd-snapshot-content">
                      <pre>{selectedFactoryRun.prdSnapshot}</pre>
                    </div>
                  )}
                </div>

                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Actualizar estado"
                    labelPlacement="floating"
                    value={selectedFactoryRun.status}
                    onIonChange={async (e: CustomEvent<any>) => {
                      const newStatus = e.detail.value;
                      if (newStatus && selectedFactoryRun) {
                        setSaving(true);
                        setError('');
                        try {
                          await updateFactoryRun(selectedFactoryRun.factoryRunId, { status: newStatus });
                          // Refresh the selected run and the list
                          const updatedRun = await getFactoryRunById(selectedFactoryRun.factoryRunId);
                          setSelectedFactoryRun(updatedRun || null);
                          setPage(0);
                          setInfiniteDisabled(false);
                          loadFactoryRuns(0, true);
                        } catch (err) {
                          setError((err as Error).message ?? 'Error actualizando el estado');
                        } finally {
                          setSaving(false);
                        }
                      }
                    }}
                    disabled={saving}
                  >
                    <IonSelectOption value="queued">En cola</IonSelectOption>
                    <IonSelectOption value="running">En ejecución</IonSelectOption>
                    <IonSelectOption value="succeeded">Exitoso</IonSelectOption>
                    <IonSelectOption value="failed">Fallido</IonSelectOption>
                    <IonSelectOption value="canceled">Cancelado</IonSelectOption>
                  </IonSelect>
                </div>
                <IonButton expand="block" onClick={() => handleEditClick(selectedFactoryRun.factoryRunId)}>
                  Editar
                </IonButton>
              </div>
            )}
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Está seguro de que desea eliminar la ejecución de fábrica: ${selectedFactoryRun?.title}?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunPage;
